'use strict';
(()=>{const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let sort='progress',loading=false,request=0;const dialog=document.createElement('dialog');dialog.id='ranking-dialog';dialog.className='account-dialog ranking-dialog';dialog.innerHTML='<header><div><span class="eyebrow">HALL OF EXPEDITIONS</span><h2>원정대 랭킹</h2></div><button id="ranking-close" aria-label="랭킹 닫기">×</button></header><div class="ranking-tabs" role="tablist"><button role="tab" data-ranking-sort="progress" aria-selected="true">최고 돌파</button><button role="tab" data-ranking-sort="power" aria-selected="false">전투력</button></div><div id="ranking-body" aria-live="polite"></div>';document.body.append(dialog);const body=$('#ranking-body');
const stats=row=>{const hero=RPG_DATA.characters[row.hero_id],job=hero?.classes[row.cell];return `${esc(hero?.name||'모험가')} · ${esc(job?.name||'')} · Lv.${Number(row.level)||1}`;};
function entry(row){const place=Number(row.rank_position),progress=Number(row.progress)||0,power=Number(row.power)||0;return `<li class="ranking-row ${row.is_me?'ranking-self':''}"><span class="ranking-place ${place<=3?'medal':''}">${place<=3?['🥇','🥈','🥉'][place-1]:place}</span><div class="ranking-person"><strong>${esc(row.expedition_name)}${row.is_me?'<em>나</em>':''}</strong><small>${stats(row)}</small></div><div class="ranking-score"><b>${sort==='power'?power.toLocaleString():progress.toLocaleString()}</b><small>${sort==='power'?'전투력':'누적 구간 돌파'}</small></div></li>`;}
async function refresh(){const id=++request,api=window.RPG_ACCOUNT_UI;loading=true;body.innerHTML='<p class="ranking-empty" role="status">원정대 기록을 불러오고 있어요…</p>';try{if(!api)throw Error('계정 연결을 준비하고 있어요. 잠시 후 다시 눌러주세요.');if(api.account.user){await api.account.refresh();if(!api.expedition.profile)await api.expedition.refreshProfile();await api.expedition.sync();}const rows=await api.expedition.list(sort);if(id!==request)return;const mine=rows.find(r=>r.is_me),top=rows.filter(r=>Number(r.rank_position)<=50);body.innerHTML=`<p class="ranking-help">클라우드에 저장한 기록으로 집계해요. 원정대마다 가장 높은 기록의 캐릭터 한 명이 표시됩니다.</p>${mine?`<section class="my-ranking"><span>내 순위</span><b>${mine.rank_position}위</b><strong>${esc(mine.expedition_name)}</strong></section>`:`<section class="ranking-join"><p>${api.account.user?(api.expedition.profile?'클라우드에 원정대를 저장하면 랭킹에 참여해요.':'원정대 이름을 정하면 랭킹을 시작할 수 있어요.'):'게스트도 랭킹을 볼 수 있어요. 참여하려면 구글로 연결해 주세요.'}</p><button data-ranking-account>계정 · 클라우드 저장</button></section>`}${top.length?`<ol class="ranking-list">${top.map(entry).join('')}</ol>`:'<div class="ranking-empty"><span>✦</span><h3>첫 번째 원정대를 기다리고 있어요</h3><p>원정대 이름을 정하고 클라우드에 기록을 저장해 보세요.</p></div>'}${mine&&Number(mine.rank_position)>50?`<ol class="ranking-list">${entry(mine)}</ol>`:''}<div class="ranking-footer"><small>최고 돌파 동률은 레벨·전투력 순으로 결정해요.</small><button data-ranking-refresh>↻ 새로고침</button></div>`;}catch(e){if(id===request)body.innerHTML=`<p class="account-notice" role="alert">${esc(e.message||'랭킹을 불러오지 못했어요.')}</p><button data-ranking-refresh>다시 시도</button>`;}finally{if(id===request)loading=false;}}
function open(){window.RPG_ACCOUNT_BRIDGE.pause(true);if(!dialog.open)dialog.showModal();refresh();}
$('#ranking-open').onclick=open;$('#ranking-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{request++;window.RPG_ACCOUNT_BRIDGE.pause(false);});document.addEventListener('rpg:ranking-open',open);dialog.onclick=e=>{const s=e.target.closest('[data-ranking-sort]');if(s){sort=s.dataset.rankingSort;dialog.querySelectorAll('[data-ranking-sort]').forEach(b=>b.setAttribute('aria-selected',String(b===s)));refresh();}if(e.target.closest('[data-ranking-refresh]')&&!loading)refresh();if(e.target.closest('[data-ranking-account]')){dialog.close();window.RPG_ACCOUNT_UI?.open();}};
})();
